      "content": "import { describe, expect, test } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';

describe('Task.complete', () => {
  test(covers(['method:Task.complete', 'criterion:0001/conclusao'], 'conclui tarefa pendente, registra TaskCompleted e rejeita repetição'), () => {
    const task = Task.create('t1', 'Comprar leite');
    task.pullEvents();
    task.complete();
    expect(task.status).toBe('completed');
    const events = task.pullEvents();
    expect(events).toHaveLength(1);
    expect(events[0]).toBeInstanceOf(TaskCompleted);
    expect(events[0]!.payload).toEqual({ taskId: 't1' });
    try {
      task.complete();
      throw new Error('deveria rejeitar');
    } catch (e) {
      expect(e).toBeInstanceOf(DomainError);
      expect((e as DomainError).code).toBe('TASK_ALREADY_COMPLETED');
    }
    expect(task.status).toBe('completed');
    expect(task.pullEvents()).toHaveLength(0);
  });
});
